"use client"
import React, {useState} from 'react'
import {useRouter} from 'next/navigation'

export default function LoginPage(){
  const [email,setEmail] = useState('')
  const [password,setPassword] = useState('')
  const [loading,setLoading] = useState(false)
  const router = useRouter()

  async function onSubmit(e:React.FormEvent){
    e.preventDefault()
    setLoading(true)
    try{
      const res = await fetch('http://localhost:3000/api/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email,password})})
      if(!res.ok) throw new Error('Invalid')
      // in mock API we get token
      const data = await res.json()
      localStorage.setItem('token',data.token || 'mocktoken')
      router.push('/dashboard')
    }catch(err){
      alert('Login failed')
    }finally{setLoading(false)}
  }

  return (
    <div style={{maxWidth:480,margin:'40px auto',padding:24,background:'#fff',borderRadius:10}}>
      <h2>Sign in</h2>
      <form onSubmit={onSubmit} style={{display:'grid',gap:12}}>
        <input placeholder="Email" value={email} onChange={e=>setEmail(e.target.value)} />
        <input placeholder="Password" type="password" value={password} onChange={e=>setPassword(e.target.value)} />
        <button disabled={loading} style={{padding:'8px 12px',background:'#059669',color:'#fff',border:'none',borderRadius:6}}>Sign in</button>
      </form>
      <p style={{marginTop:12}}>New here? <a href="/register">Create an account</a></p>
    </div>
  )
}
"use client"
import React, { useState } from 'react'
import { login } from '../../../lib/api'

export default function LoginPage() {
  const [phoneOrEmail, setPhoneOrEmail] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setLoading(true)
    setError(null)
    try {
      await login({ identifier: phoneOrEmail })
      // redirect to dashboard
      window.location.href = '/dashboard'
    } catch (err: any) {
      setError(err?.message || 'Login failed')
    } finally { setLoading(false) }
  }

  return (
    <div className="max-w-md mx-auto mt-12">
      <h1 className="text-2xl font-semibold mb-4">Sign in</h1>
      <form onSubmit={handleSubmit} className="space-y-3">
        <input value={phoneOrEmail} onChange={e=>setPhoneOrEmail(e.target.value)} placeholder="Phone or email" className="w-full p-3 border rounded" />
        <button disabled={loading} className="w-full bg-blue-600 text-white p-3 rounded">{loading ? 'Sending...' : 'Send OTP / Login'}</button>
        {error && <div className="text-red-600">{error}</div>}
      </form>
    </div>
  )
}
